import { Button, EmptyState, StatusDot, Timestamp, useI18n, type DateInput, type StatusDotTone } from '@gntik-ai/ui';
import { useState } from 'react';
import { DEPLOYMENT_EVENTS } from './fixtures';

export interface StatusEvent {
  id: string;
  /** Short state name next to the dot ("Running"). */
  status: string;
  tone: StatusDotTone;
  title: string;
  description?: string;
  at: DateInput;
  /** Who or what caused the change. */
  actor?: string;
  /** Pulses the dot (the current, in-progress state). */
  live?: boolean;
}

export interface StatusTimelineProps {
  /** Events, newest first. */
  events?: readonly StatusEvent[];
  /** Accessible name of the list. */
  label?: string;
  /** Title shown when events is an explicit empty array. */
  emptyLabel?: string;
  /** Collapse toggle text. */
  showFewerLabel?: string;
  /** Expand toggle text, given the number of hidden events. */
  showEarlierLabel?: (hidden: number) => string;
  /** Prefix before the actor's name. */
  actorLabel?: string;
  /** Events shown before "Show earlier"; all when omitted. */
  maxVisible?: number;
  /** `relative` ("3 hours ago") or `absolute` timestamps. */
  timeFormat?: 'relative' | 'absolute';
  className?: string;
}

/** Vertical timeline of state changes, or a named empty state for an explicit empty events array. */
export function StatusTimeline({
  events = DEPLOYMENT_EVENTS,
  label: labelProp,
  emptyLabel: emptyLabelProp,
  showFewerLabel: showFewerLabelProp,
  showEarlierLabel: showEarlierLabelProp,
  actorLabel: actorLabelProp,
  maxVisible,
  timeFormat = 'relative',
  className,
}: StatusTimelineProps) {
  const { t } = useI18n();
  const label = labelProp ?? t('statusTimeline.label');
  const emptyLabel = emptyLabelProp ?? t('statusTimeline.empty');
  const showFewerLabel = showFewerLabelProp ?? t('statusTimeline.showFewer');
  const showEarlierLabel = showEarlierLabelProp ?? ((count: number) => t('statusTimeline.showEarlier', { count }));
  const actorLabel = actorLabelProp ?? t('statusTimeline.actor');
  const [expanded, setExpanded] = useState(false);
  if (events.length === 0) {
    return <EmptyState role="region" aria-label={label} size="sm" title={emptyLabel} className={className} />;
  }
  const limit = !expanded && maxVisible !== undefined ? maxVisible : events.length;
  const shown = events.slice(0, limit);
  const hidden = events.length - shown.length;
  return (
    <div className={className}>
      <ol aria-label={label} className="flex flex-col">
        {shown.map((event, i) => {
          const last = i === shown.length - 1;
          return (
            <li key={event.id} className="relative flex gap-3 pb-6 last:pb-0">
              {!last && <span aria-hidden className="absolute top-5 bottom-0 start-[9px] w-px bg-border" />}
              <span className="relative z-10 mt-1 flex size-5 shrink-0 items-center justify-center rounded-full bg-card">
                <StatusDot tone={event.tone} pulse={event.live} size="lg" />
              </span>
              <div className="min-w-0 flex-1">
                <div className="flex flex-col gap-0.5 sm:flex-row sm:items-baseline sm:justify-between sm:gap-4">
                  <p className="text-[13px] text-foreground">
                    <span className="font-semibold">{event.status}</span>
                    <span className="text-muted-foreground"> · </span>
                    {event.title}
                  </p>
                  <Timestamp value={event.at} format={timeFormat} className="shrink-0 font-mono text-[11px]" />
                </div>
                {(event.description || event.actor) && (
                  <p className="mt-0.5 text-[12.5px] text-muted-foreground">
                    {event.description}
                    {event.description && event.actor && ' '}
                    {event.actor && <span>{`${actorLabel} `}{event.actor}</span>}
                  </p>
                )}
              </div>
            </li>
          );
        })}
      </ol>
      {(hidden > 0 || (expanded && maxVisible !== undefined && events.length > maxVisible)) && (
        <Button variant="ghost" size="sm" className="mt-3 ms-6" aria-expanded={expanded} onClick={() => setExpanded((v) => !v)}>
          {expanded ? showFewerLabel : showEarlierLabel(hidden)}
        </Button>
      )}
    </div>
  );
}

import type { StatusEvent } from './StatusTimeline';

const HOUR = 3_600_000;
/** Fixtures are relative to load time so relative timestamps stay fresh in the docs. */
export const FIXTURE_NOW = Date.now();

/** State changes of a deployment, newest first. */
export const DEPLOYMENT_EVENTS: StatusEvent[] = [
  { id: 'e6', status: 'Running', tone: 'success', title: 'Deployment healthy', description: 'All 3 replicas passed health checks.', at: FIXTURE_NOW - 0.2 * HOUR, actor: 'System', live: true },
  { id: 'e5', status: 'Deploying', tone: 'info', title: 'Rolling out v2.14.0', description: 'Canary at 10%, then 50%, then 100%.', at: FIXTURE_NOW - 0.6 * HOUR, actor: 'Ana Lopez' },
  { id: 'e4', status: 'Approved', tone: 'primary', title: 'Release approved', at: FIXTURE_NOW - 1.5 * HOUR, actor: 'Sam Carter' },
  { id: 'e3', status: 'Degraded', tone: 'warning', title: 'Error rate above 2%', description: 'Alert fired on orders-api.', at: FIXTURE_NOW - 5 * HOUR, actor: 'Monitoring' },
  { id: 'e2', status: 'Failed', tone: 'destructive', title: 'Build failed', description: 'Type check failed in 2 files.', at: FIXTURE_NOW - 26 * HOUR, actor: 'CI' },
  { id: 'e1', status: 'Created', tone: 'neutral', title: 'Deployment created', at: FIXTURE_NOW - 50 * HOUR, actor: 'Ana Lopez' },
];
